// Раскладка клавиатуры УК-НЦ (МС7007) для клавиатуры хоста.
//
// Слева клавиша хоста, справа НОМЕР клавиши машины - тот же, что в
// uknc.keys, где он привязан к рисунку. Контроллер отдаёт номер клавиши, а
// не код символа; разряд 7 регистра 177702 означает отпускание, а в символы
// всё переводит ПЗУ машины. Поэтому модификаторов вида /S здесь нет: РУС и
// регистр - забота самой машины, и `use_remap = 0` у устройства.
//
// Отсюда же правило для верхнего регистра: знак, который на машине набирают
// с НР, отдан тому же номеру, что и его нижний сосед, с пометкой `+shift`, а
// знак нижнего регистра - с пометкой `-shift`. Регистры хоста и машины
// расходятся: `'` на хосте без Shift, а на МС7007 это НР и 7; `:` на хосте с
// Shift, а на МС7007 без НР. На время нажатия помеченной клавиши НР ставится
// в нужное положение, а потом возвращается туда, где его держит Shift хоста.
// Без пометки (буквы, управляющие) Shift хоста просто прижимает НР - так
// переключается регистр букв.
//
// Номера сняты с ПЗУ машины, вывод - в заголовке uknc.keys.
//
// Числа восьмеричные: у машины radix = 8.

// --- Буквы ------------------------------------------------------------
// Клавиша хоста отдана клавише машины с той же ЛАТИНСКОЙ надписью, поэтому
// в латинском регистре хост печатает то, что на нём написано, а в русском
// получается ЯВЕРТЫ - как и на самой машине.
A:              &72     // А
B:              &76     // Б
C:              &50     // Ц
D:              &57     // Д
E:              &33     // Е
F:              &47     // Ф
G:              &55     // Г
H:              &156    // Х
I:              &73     // И
J:              &27     // Й
K:              &52     // К
L:              &56     // Л
M:              &112    // М
N:              &54     // Н
O:              &75     // О
P:              &53     // П
Q:              &67     // Я
R:              &74     // Р
S:              &111    // С
T:              &114    // Т
U:              &51     // У
V:              &137    // Ж
W:              &71     // В
X:              &115    // Ь
Y:              &70     // Ы
Z:              &157    // З

// --- Цифровой ряд и его верхний регистр -------------------------------
1:              &30   -shift
2:              &31   -shift
3:              &32   -shift
4:              &13   -shift
5:              &34   -shift
6:              &35   -shift
7:              &16   -shift
8:              &17   -shift
9:              &177  -shift
0:              &176  -shift
!:              &30   +shift
":              &31   +shift
#:              &32   +shift
$:              &13   +shift
%:              &34   +shift
&:              &35   +shift
':              &16   +shift
(:              &17   +shift
):              &177  +shift

// --- Знаки ------------------------------------------------------------
semicolon:      &7    -shift    // ; +
plus:           &7    +shift
colon:          &174  -shift    // : *
*:              &174  +shift
,:              &117  -shift    // , <
<:              &117  +shift
.:              &135  -shift    // . >
>:              &135  +shift
slash:          &173  -shift    // / ?
?:              &173  +shift
minus:          &175  -shift    // - =
=:              &175  +shift
[:              &36     // Ш [
{:              &36
]:              &37     // Щ ]
}:              &37
\:              &136    // Э \
bar:            &136
circum:         &110    // Ч ^
under:          &155    // Ъ _
@:              &77     // Ю @

// --- Управляющие ------------------------------------------------------
space:          &113
tab:            &26
esc:            &6      // АР2
ret:            &153    // ВК
enter:          &166    // ВВОД цифрового блока
back:           &132    // ЗБ
del:            &132
left:           &116
right:          &133
up:             &154
down:           &134

// --- Регистровые ------------------------------------------------------
shift:          &105    // НР
ctrl:           &46     // УПР
alt:            &66     // ГРАФ
caps:           &107    // ФИКС

// --- Функциональные ---------------------------------------------------
f1:             &10     // К1
f2:             &11     // К2
f3:             &12     // К3
f4:             &14     // К4
f5:             &15     // К5
f6:             &106    // АЛФ, пока нажата - другой алфавит
f7:             &172    // ПОМ
f8:             &151    // ИСП
f9:             &152    // УСТ
f10:            &171    // СБРОС, очистка экрана
f12:            &4      // СТОП, ставит HALT центральному процессору
